import java.io.*;

public class Main {
    static long lower, upper;
    static long[] pre, scratch;

    // sorts pre[lo, hi) and counts pairs i < j in it with lower <= pre[j] - pre[i] <= upper
    static long sortCount(int lo, int hi) {
        if (hi - lo <= 1) return 0;
        int mid = (lo + hi) >>> 1;
        long count = sortCount(lo, mid) + sortCount(mid, hi);
        int l = mid, r = mid;
        for (int i = lo; i < mid; i++) {
            while (l < hi && pre[l] - pre[i] < lower) l++;
            while (r < hi && pre[r] - pre[i] <= upper) r++;
            count += r - l;
        }
        int i = lo, j = mid, k = lo;
        while (i < mid && j < hi) scratch[k++] = pre[i] <= pre[j] ? pre[i++] : pre[j++];
        while (i < mid) scratch[k++] = pre[i++];
        while (j < hi) scratch[k++] = pre[j++];
        System.arraycopy(scratch, lo, pre, lo, hi - lo);
        return count;
    }

    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));
        int n = (int) readLong(in);
        pre = new long[n + 1];
        scratch = new long[n + 1];
        for (int i = 1; i <= n; i++) pre[i] = pre[i - 1] + readLong(in);
        lower = readLong(in);
        upper = readLong(in);
        System.out.println(sortCount(0, n + 1));
    }

    static long readLong(DataInputStream in) throws IOException {
        int c = in.read();
        while (c != '-' && (c < '0' || c > '9')) c = in.read();
        boolean neg = c == '-';
        if (neg) c = in.read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = in.read(); }
        return neg ? -r : r;
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

var lower, upper int64
var pre, scratch []int64

// sorts pre[lo, hi) and counts pairs i < j in it with lower <= pre[j] - pre[i] <= upper
func sortCount(lo, hi int) int64 {
	if hi-lo <= 1 {
		return 0
	}
	mid := (lo + hi) / 2
	count := sortCount(lo, mid) + sortCount(mid, hi)
	l, r := mid, mid
	for i := lo; i < mid; i++ {
		for l < hi && pre[l]-pre[i] < lower {
			l++
		}
		for r < hi && pre[r]-pre[i] <= upper {
			r++
		}
		count += int64(r - l)
	}
	i, j, k := lo, mid, lo
	for i < mid && j < hi {
		if pre[i] <= pre[j] {
			scratch[k] = pre[i]
			i++
		} else {
			scratch[k] = pre[j]
			j++
		}
		k++
	}
	k += copy(scratch[k:], pre[i:mid])
	copy(scratch[k:], pre[j:hi])
	copy(pre[lo:hi], scratch[lo:hi])
	return count
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() int64 {
		sc.Scan()
		v, _ := strconv.ParseInt(sc.Text(), 10, 64)
		return v
	}
	n := int(next())
	pre = make([]int64, n+1)
	scratch = make([]int64, n+1)
	for i := 1; i <= n; i++ {
		pre[i] = pre[i-1] + next()
	}
	lower, upper = next(), next()
	fmt.Println(sortCount(0, n+1))
}
